from pathlib import Path
import json,html
P=Path('pilotos-vectoriales');m=json.loads((P/'manifest.json').read_text())
names=['Firma SanSi Cup','Galano','Perrito','Gatita']
notes=['El lettering elegido, trazado por colores. Se conservan los remates de la firma.','Frente azul, corona amarilla y pico curvo; plumaje reducido a masas.','Orejas caídas, hocico claro y chaqueta; pelaje resumido en la silueta.','Manchas asimétricas y mirada verde. Sin corazón.']
head='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SanSi Cup · cuatro pilotos</title><style>
*{box-sizing:border-box}body{margin:0;background:#eeeae1;color:#14286e;font:16px/1.5 system-ui}main{max-width:1220px;margin:auto;padding:36px 24px 70px}h1{font-size:clamp(36px,5vw,65px);line-height:1.05;letter-spacing:-.05em;margin:12px 0 20px}h2{font-size:24px;line-height:1.2}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.16em}.intro{max-width:720px}.links{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0 40px}.button{padding:12px 20px;background:#14286e;color:white;border-radius:30px;text-decoration:none}.button.secondary{background:white;color:#14286e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}article{background:white;border-radius:20px;overflow:hidden}.preview{display:block;background:#e8e5df;padding:24px}.preview img{display:block;width:100%;height:430px;object-fit:contain}.info{padding:22px}.info h2{margin:0 0 10px}.info p{color:#384451}.downloads{display:flex;gap:20px}a{color:inherit}.ref{margin-top:22px;border-top:1px solid #ddd;padding-top:18px;display:flex;gap:20px;align-items:center}.ref img{width:120px;height:140px;object-fit:contain;background:#eeeae1;border-radius:8px}.ref span{font-size:13px;color:#384451}.footer{margin-top:36px;border-top:1px solid #c7c7c7;padding-top:18px;font-size:14px}@media(max-width:750px){.grid{grid-template-columns:1fr}.preview img{height:340px}}
</style><main><div class="eyebrow">SanSi Cup 2026 · ronda de aprobación</div><h1>Cuatro pilotos.<br>Una misma firma.</h1><p class="intro">Lettering, Galano, perrito y gatita. Revisa el parecido y el carácter del dibujo antes de extender esta dirección a las otras dieciséis piezas.</p><div class="links"><a class="button" href="prueba-pilotos-4cm.pdf">PDF a tamaño real · 4 cm</a><a class="button secondary" href="pilotos-vectoriales.zip" download>Descargar los cuatro pilotos</a><a class="button secondary" href="../galeria-stickers.html">Selección de conceptos</a></div><div class="grid">'''
parts=[head]
for i,a in enumerate(m):
 parts.append(f'''<article><a class="preview" href="svg/{a['id']}.svg"><img src="svg/{a['id']}.svg" alt="{names[i]} · piloto vectorial"></a><div class="info"><div class="eyebrow">Piloto {i+1:02} / 04</div><h2>{names[i]}</h2><p>{notes[i]}</p><div class="downloads"><a href="svg/{a['id']}.svg" download>SVG editable</a><a href="png/{a['id']}.png" download>PNG transparente</a></div><div class="ref"><a href="referencias/{a['animal']}.png"><img src="referencias/{a['animal']}.png" alt="Referencia de {names[i]}"></a><span>Referencia utilizada<br><br>Prueba: {a['width_mm']:.1f} × {a['height_mm']:.1f} mm<br>Borde blanco incluido: 2 mm</span></div></div></article>''')
parts.append('''</div><p class="footer">Para comprobar los 4 cm, imprime la primera página del PDF al 100 %, sin ajustar al papel. Las páginas siguientes muestran comparaciones ampliadas. Estos son pilotos para aprobación, todavía no la entrega de producción.</p></main></html>''')
(P/'index.html').write_text(''.join(parts))
f=Path('galeria-stickers.html');s=f.read_text();start='<section id="pilotos-actuales"';
if start not in s:
 s=s.replace('<main>','<main><section id="pilotos-actuales" style="background:#14286e;color:white;padding:28px;border-radius:18px;margin-bottom:32px"><h2 style="margin:0 0 12px">Nueva ronda: cuatro pilotos vectoriales</h2><p>Lettering, Galano, perrito y gatita. PDF a 4 cm y archivos SVG para revisar.</p><a href="pilotos-vectoriales/index.html" style="font-size:22px;font-weight:700">Abrir los cuatro pilotos →</a></section>',1)
 s=s.replace('Primero se revisarán cuatro pilotos.','Los cuatro pilotos ya están disponibles en el enlace superior.')
 f.write_text(s)
print('Galería de pilotos creada; acceso añadido a la galería principal.')
